VIEWS = [('ducks', "__goto('city');wxForce('sun');P.x=33.9;P.z=-38.3;S.bag.bread=(S.bag.bread||0)+1;feedDucks(0);__run(90);const ds=LOC.city.ducks.filter(d=>d.pond===0);if(ds.length){const cx=ds.reduce((a,d)=>a+d.x,0)/ds.length,cz=ds.reduce((a,d)=>a+d.z,0)/ds.length;P.yaw=Math.atan2(-(cx-P.x),-(cz-P.z));P.pitch=-Math.atan2(1.3,Math.hypot(cx-P.x,cz-P.z));}JSON.stringify(ds.map(d=>[+d.x.toFixed(2),+d.z.toFixed(2),+d.g.rotation.y.toFixed(2),+Math.atan2(P.x-d.x,P.z-d.z).toFixed(2)]))"), ('ducks-later', '__run(60);const ds=LOC.city.ducks.filter(d=>d.pond===0);JSON.stringify(ds.map(d=>[+d.x.toFixed(2),+d.z.toFixed(2),+d.g.rotation.y.toFixed(2),+Math.atan2(P.x-d.x,P.z-d.z).toFixed(2)]))')]